/**
 * Idle-game balance simulation.
 *
 * Model
 * -----
 * - 5 generator tiers, i = 0..4.
 * - Base cost of tier i:            costBase(i)   = 10 * 8^i
 * - Base production of tier i:      prod(i)       = 1 * 3^i gold / tick
 * - Each purchase of a tier escalates THAT tier's next-unit cost by a
 *   constant factor (standard idle-game mechanic):
 *       unitCost(i, owned)          = 10 * 8^i * COST_COUNT_GROWTH^owned
 *
 *   Without per-purchase escalation the payback of tier i,
 *   10 * 8^i / 3^i = 10 * (8/3)^i, would be strictly increasing in i and
 *   the cheapest-payback strategy would forever buy only tier 0. Escalation
 *   makes paybacks cross so higher tiers eventually become optimal.
 *
 * Strategy: on every tick, first accrue gold from owned generators, then buy
 * ONE unit of the affordable tier with the smallest payback
 * (cost / production). If nothing is affordable, bank the gold.
 */

export const TIERS = 5;
export const BASE_COST = 10;
export const COST_TIER_GROWTH = 8;
export const BASE_PROD = 1;
export const PROD_TIER_GROWTH = 3;
/** Per-purchase cost escalation factor for each individual tier. */
export const COST_COUNT_GROWTH = 2;

export interface PurchaseEvent {
  tick: number;
  tier: number;
  /** Cost paid for this unit. */
  cost: number;
  /** Total gold-per-tick rate immediately after this purchase. */
  rateAfter: number;
}

export interface SimResult {
  totalTicks: number;
  finalGold: number;
  /** Owned units per tier at end of run. */
  counts: number[];
  /** Chronological purchase log. */
  purchases: PurchaseEvent[];
  /**
   * Gold-per-tick production rate sampled at the START of every tick
   * (i.e. before that tick's income and purchase).
   */
  rateSeries: Float64Array;
}

/** Cost of the next unit of `tier`, given `owned` units already held. */
export function unitCost(tier: number, owned: number): number {
  return (
    BASE_COST * Math.pow(COST_TIER_GROWTH, tier) * Math.pow(COST_COUNT_GROWTH, owned)
  );
}

/** Production per tick of a single unit of `tier`. */
export function unitProduction(tier: number): number {
  return BASE_PROD * Math.pow(PROD_TIER_GROWTH, tier);
}

/** Payback period in ticks for the next unit of `tier`. */
export function payback(tier: number, owned: number): number {
  return unitCost(tier, owned) / unitProduction(tier);
}

export function totalRate(counts: readonly number[]): number {
  let r = 0;
  for (let t = 0; t < TIERS; t++) r += counts[t] * unitProduction(t);
  return r;
}

/** Run the simulation headless for `totalTicks` ticks. Fully deterministic. */
export function runSim(totalTicks = 50_000): SimResult {
  let gold = 0;
  const counts = new Array<number>(TIERS).fill(0);
  const purchases: PurchaseEvent[] = [];
  const rateSeries = new Float64Array(totalTicks);

  for (let tick = 0; tick < totalTicks; tick++) {
    // Income for this tick comes from generators owned at tick start.
    const rate = totalRate(counts);
    rateSeries[tick] = rate;
    gold += rate;

    // Buy the affordable purchase with the smallest payback (one per tick).
    let bestTier = -1;
    let bestPayback = Infinity;
    let bestCost = Infinity;
    for (let t = 0; t < TIERS; t++) {
      const c = unitCost(t, counts[t]);
      if (gold >= c) {
        const pb = c / unitProduction(t);
        if (pb < bestPayback) {
          bestPayback = pb;
          bestTier = t;
          bestCost = c;
        }
      }
    }
    if (bestTier >= 0) {
      gold -= bestCost;
      counts[bestTier]++;
      purchases.push({
        tick,
        tier: bestTier,
        cost: bestCost,
        rateAfter: totalRate(counts),
      });
    }
  }

  return { totalTicks, finalGold: gold, counts, purchases, rateSeries };
}

