import { createHash } from "node:crypto";
import type { SimResult } from "./sim.js";
import { TIERS } from "./sim.js";

/** Stable SHA-256 hash over the purchase log (tick/tier pairs only). */
export function hashPurchaseLog(sim: SimResult): string {
  const h = createHash("sha256");
  for (const p of sim.purchases) {
    h.update(`${p.tick},${p.tier};`);
  }
  return h.digest("hex");
}

/** First tick at which each tier was purchased, or null if never. */
export function firstPurchaseTicks(sim: SimResult): (number | null)[] {
  const first: (number | null)[] = new Array<number | null>(TIERS).fill(null);
  for (const p of sim.purchases) {
    if (first[p.tier] === null) first[p.tier] = p.tick;
  }
  return first;
}

/** True iff every sampled rate is >= its predecessor. */
export function isNonDecreasing(series: ArrayLike<number>): boolean {
  for (let i = 1; i < series.length; i++) {
    if (series[i] < series[i - 1]) return false;
  }
  return true;
}

