import { describe, expect, it } from "vitest";
import { runSim } from "../src/sim.js";
import { firstPurchaseTicks, hashPurchaseLog, isNonDecreasing } from "../src/stats.js";

describe("idle-game balance sim (50,000 ticks)", () => {
  it("keeps gold-per-tick non-decreasing over time", () => {
    const sim = runSim();
    expect(sim.rateSeries.length).toBe(50_000);
    expect(isNonDecreasing(sim.rateSeries)).toBe(true);
  });

  it("purchases every tier at least once", () => {
    const sim = runSim();
    const counts = sim.counts;
    for (let t = 0; t < counts.length; t++) {
      expect(counts[t], `tier ${t} count`).toBeGreaterThan(0);
    }
  });

  it("has strictly increasing time-to-first-purchase across tiers", () => {
    const sim = runSim();
    const first = firstPurchaseTicks(sim);
    for (let t = 0; t < first.length; t++) {
      expect(first[t], `tier ${t} first purchase`).not.toBeNull();
      if (t > 0) {
        expect(first[t]!, `tier ${t} vs tier ${t - 1}`).toBeGreaterThan(first[t - 1]!);
      }
    }
  });

  it("is deterministic: two runs produce identical hashed purchase logs", () => {
    const a = runSim();
    const b = runSim();
    const ha = hashPurchaseLog(a);
    const hb = hashPurchaseLog(b);
    expect(ha).toBe(hb);
    // The log must be substantive, not vacuously equal.
    expect(a.purchases.length).toBeGreaterThan(100);
    expect(ha).toMatch(/^[0-9a-f]{64}$/);
  });
});

