import { writeFileSync } from "node:fs";
import { runSim, unitCost, TIERS, COST_COUNT_GROWTH } from "./sim.js";
import { firstPurchaseTicks, hashPurchaseLog } from "./stats.js";

const TICKS = 50_000;
const sim = runSim(TICKS);
const first = firstPurchaseTicks(sim);

const rows = TIERS >= 0 ? [] : [];
for (let t = 0; t < TIERS; t++) {
  rows.push(
    `| ${t} | ${first[t] ?? "—"} | ${sim.counts[t]} | \`${unitCost(t, 0)} × ${COST_COUNT_GROWTH}^n\` |`
  );
}

const md = `# Idle-Game Balance Report

- Ticks simulated: **${TICKS.toLocaleString("en-US")}** (headless)
- Purchase log SHA-256: \`${hashPurchaseLog(sim)}\`
- Total purchases: **${sim.purchases.length.toLocaleString("en-US")}**
- Final gold-per-tick rate: **${sim.rateSeries[TICKS - 1].toLocaleString("en-US")}**
- Leftover gold at end of run: **${Math.round(sim.finalGold).toLocaleString("en-US")}**

## Model

| Parameter | Value |
|---|---|
| Tiers | ${TIERS} |
| Base cost of tier i | \`10 · 8^i\` |
| Production of tier i | \`1 · 3^i\` gold/tick |
| Per-purchase cost escalation | \`× ${COST_COUNT_GROWTH}\` per unit owned of that tier |
| Strategy | Each tick, buy the affordable tier with the smallest payback (cost ÷ production), one purchase per tick |

Per-purchase escalation is required for the "cheapest payback" rule to ever
leave tier 0: without it the payback \`10·(8/3)^i\` is strictly increasing in
the tier index and higher tiers would never be bought.

## First-purchase ticks and final counts

| Tier | First-purchase tick | Final count | Cost formula |
|---:|---:|---:|---|
${rows.join("\n")}

## Balance properties verified by \`npx vitest run\`

1. Gold-per-tick is non-decreasing over the whole run.
2. Every tier is purchased at least once.
3. Time-to-first-purchase is strictly increasing with tier.
4. The run is deterministic — identical runs hash to the same purchase-log digest.
`;

writeFileSync("report.md", md);
console.log("Wrote report.md");

